    fun has(name:String)=name in grids
    private fun azulSpecial(hm:Int):String?{
        var c:HttpURLConnection?=null
        return try{
            c=URL("https://azulfm.com.uy/vivo.php").openConnection() as HttpURLConnection
            c.connectTimeout=5000;c.readTimeout=5000;c.setRequestProperty("User-Agent","RadioRocky35")
            val a=JSONArray(c.inputStream.bufferedReader().use{it.readText()})
            (0 until a.length()).map{a.getJSONObject(it)}.firstOrNull{hm>=(it.optString("hm_desde").toIntOrNull()?:9999)&&hm<=(it.optString("hm_hasta").toIntOrNull()?:-1)}?.optString("titulo")?.takeIf{it.isNotBlank()}
        }catch(_:Exception){null}finally{c?.disconnect()}
    }
    // Devuelve "🎙 programa" o "" si no hay dato seguro.
    fun current(name:String):String{
        val g=grids[name]?:return ""
        val c=Calendar.getInstance(TimeZone.getTimeZone("America/Montevideo"))
        val day=c.get(Calendar.DAY_OF_WEEK);val hm=c.get(Calendar.HOUR_OF_DAY)*100+c.get(Calendar.MINUTE)
        if(name==AZUL)azulSpecial(hm)?.let{return "🎙 $it"}
        g.firstOrNull{it.day==day&&hm in it.from..it.to}?.let{return "🎙 "+it.text}
        return if(name==AZUL)"🎙 Selección musical" else ""
    }
